        defaultAt,
        lessThan(releaseBranchAt),
        reason: 'AC5: the fail-safe default precedes the release arm',
      );
      expect(
        script,
        contains('::warning::'),
        reason: 'AC5: an API failure degrades loudly, never silently',
      );
